import { existsSync } from 'node:fs';

/**
 * Loads a service's local `.env` (generated by `pnpm bootstrap`) when present.
 * Variables already set in the real environment always win, so CI, staging
 * and production configuration is never overridden by a stray file.
 */
export function loadLocalEnvFile(path = '.env'): void {
  if (existsSync(path)) process.loadEnvFile(path);
}
